    "description": "纪念邹家华同志诞辰100周年座谈会29日在京举行。中共中央政治局常委、全国人大常委会委员长赵乐际出席座谈会，并在会前会见了邹家华同志亲属。 邹家华同志是中国共产党的优秀党员，久经考验的忠诚的共产主义战士，无产阶级革命家，中国共产党第十四届中央政治局委员，国务院原副总理，第九届全国人民代表大会常务委员会副委员长。 中共中央政治局委员、国务院副总理张国清在座谈会上缅怀了邹家华同志光辉的一生，表示要学习他信念坚定、对党忠诚的政治品格，实事求是…",
    "content": "纪念邹家华同志诞辰100周年座谈会29日在京举行。中共中央政治局常委、全国人大常委会委员长赵乐际出席座谈会，并在会前会见了邹家华同志亲属。 邹家华同志是中国共产党的优秀党员，久经考验的忠诚的共产主义战士，无产阶级革命家，中国共产党第十四届中央政治局委员，国务院原副总理，第九届全国人民代表大会常务委员会副委员长。 中共中央政治局委员、国务院副总理张国清在座谈会上缅怀了邹家华同志光辉的一生，表示要学习他信念坚定、对党忠诚的政治品格，实事求是、求真务实的工作作风，锐意改革、敢于作为的奋斗精神，朴实无华、严于律己的优良风范…"
