    "description": "中新社北京9月29日电 (记者 王梦瑶)中国电力规划设计总院29日在北京发布的《中国电力发展报告2026》预计，2026年中国全社会用电量达11万亿千瓦时，同比增长6%。这一数据将在2027年升至11.6万亿千瓦时，2028年达到12.2万亿千瓦时。",
    "content": "中新社北京9月29日电 (记者 王梦瑶)中国电力规划设计总院29日在北京发布的《中国电力发展报告2026》预计，2026年中国全社会用电量达11万亿千瓦时，同比增长6%。这一数据将在2027年升至11.6万亿千瓦时，2028年达到12.2万亿千瓦时。"
