    "pub_date": "2026-09-29 19:05:50",
    "author": "孙敏",
    "description": "9月28日下午，马来西亚华人张慧清离开昆明前，将辗转找到的太伯公郑锦来的照片，亲手贴到了昆明侨光小学的南侨机工英雄墙上。此前，她因在昆明街头偶遇外公邝金源的照片而引发广泛关注。照片贴完了，但郑锦来后来在哪里生活、后人如今在哪里，张慧清仍在寻找。收集汇总更多南侨机工信息，帮助更多后人找到先辈的足迹，成了她此行之后最大的心愿。 9月16日，马来西亚华人张慧清在昆明街头与外公邝金源的照片合影。新华社发 记者：孙敏 新华社音视频部制作",
    "content": "9月28日下午，马来西亚华人张慧清离开昆明前，将辗转找到的太伯公郑锦来的照片，亲手贴到了昆明侨光小学的南侨机工英雄墙上。此前，她因在昆明街头偶遇外公邝金源的照片而引发广泛关注。照片贴完了，但郑锦来后来在哪里生活、后人如今在哪里，张慧清仍在寻找。收集汇总更多南侨机工信息，帮助更多后人找到先辈的足迹，成了她此行之后最大的心愿。 9月16日，马来西亚华人张慧清在昆明街头与外公邝金源的照片合影。新华社发 记者：孙敏 新华社音视频部制作"
