    "author": "",
    "description": "中新网广州9月29日电 (记者 王坚)2026年广东省全国科普月暨第九届广东科普嘉年华成果交流主会场活动29日在位于广州的广东科学中心启动。该活动汇聚优质科普与科创资源，通过多展区、多主题、沉浸式互动体验，全方位展示广东科普事业发展成果与科技创新实践成效，为民众打造了一场可看、可触、可体验的全民科普盛宴。",
    "content": "中新网广州9月29日电 (记者 王坚)2026年广东省全国科普月暨第九届广东科普嘉年华成果交流主会场活动29日在位于广州的广东科学中心启动。该活动汇聚优质科普与科创资源，通过多展区、多主题、沉浸式互动体验，全方位展示广东科普事业发展成果与科技创新实践成效，为民众打造了一场可看、可触、可体验的全民科普盛宴。"
