    "description": "丰收时节，位于云南省元阳县的世界遗产哈尼梯田稻浪翻金。74岁的美国游客迈克尔·劳伦斯再次踏入哈尼梯田。 他是一名摄影和徒步爱好者，自2017年首次到访元阳哈尼梯田后，便与这片世界文化遗产结下深厚情缘。 2026年秋收，这是他的第12次元阳之旅。他走进梯田，亲自参与收割、打谷，沉浸式体验哈尼传统农耕文化；走入哈尼村庄，逛市集，感受民族烟火气；走进村民家中，品尝哈尼古树茶，和村民共享丰收盛宴。 多年来，他记录梯田四季风光与本土人文，持续在海…",
    "content": "丰收时节，位于云南省元阳县的世界遗产哈尼梯田稻浪翻金。74岁的美国游客迈克尔·劳伦斯再次踏入哈尼梯田。 他是一名摄影和徒步爱好者，自2017年首次到访元阳哈尼梯田后，便与这片世界文化遗产结下深厚情缘。 2026年秋收，这是他的第12次元阳之旅。他走进梯田，亲自参与收割、打谷，沉浸式体验哈尼传统农耕文化；走入哈尼村庄，逛市集，感受民族烟火气；走进村民家中，品尝哈尼古树茶，和村民共享丰收盛宴。 多年来，他记录梯田四季风光与本土人文，持续在海外社交平台发布影像作品，向世界推介元阳哈尼梯田。 作者：何春好、邓娇、陈萍、李寒…"
