    "content": "中新社海南文昌9月29日电 (记者 符宇群)海南商业航天发射场二期项目29日正式启动合练。项目建有两个通用型中型液体发射工位，可为长征十二号B等5米直径以下两级构型火箭提供发射服务。经过后续合练和测试，两个发射工位计划今年底具备执行任务能力。"
