    "description": "我之前一直都是windows,自学编程时一直使用到是vscode，vscode的开箱即用和方便的插件管理我很喜欢，但就如有一位up主所说的，“他不想使用浏览器编程，所以他使用了nvim\",后来我在挑选我linux操作系统下的编辑器时，我换成了nvim,尽管现在我形成了使用vim快捷键的习惯，但nvim众多的插件让我很难抉择，lazyvim,我感觉有些臃肿。所以我就换成了helix。可能是我行动很差吧 现在我白天的时间全去上课了，为什么学…",
    "content": "我之前一直都是windows,自学编程时一直使用到是vscode，vscode的开箱即用和方便的插件管理我很喜欢，但就如有一位up主所说的，“他不想使用浏览器编程，所以他使用了nvim\",后来我在挑选我linux操作系统下的编辑器时，我换成了nvim,尽管现在我形成了使用vim快捷键的习惯，但nvim众多的插件让我很难抉择，lazyvim,我感觉有些臃肿。所以我就换成了helix。可能是我行动很差吧 现在我白天的时间全去上课了，为什么学校有早八还是双及格制啊......"
