    "description": "9月29日，东莞市博物馆新馆正式开馆。 新馆构建“一馆通古今”的展陈体系，打造九大主题展览，涵盖通史陈列、馆藏臻宝、书画艺术、数字文博及当代艺术等多元板块，总建筑面积超4万平方米，是集文物收藏、学术研究、文化展示、社会教育、公共服务于一体的区域性综合博物馆。 记者：李思佳 新华社音视频部制作",
    "content": "9月29日，东莞市博物馆新馆正式开馆。 新馆构建“一馆通古今”的展陈体系，打造九大主题展览，涵盖通史陈列、馆藏臻宝、书画艺术、数字文博及当代艺术等多元板块，总建筑面积超4万平方米，是集文物收藏、学术研究、文化展示、社会教育、公共服务于一体的区域性综合博物馆。 记者：李思佳 新华社音视频部制作"
