    "description": "新华社耶路撒冷9月29日电（记者冯国芮 庞昕熠）以色列国防军和以色列国家安全总局（辛贝特）29日发表联合声明称，以方28日夜间至29日凌晨在加沙地带北部采取行动，打死巴勒斯坦伊斯兰抵抗运动（哈马斯）军事分支北加沙旅指挥官伊兹丁·比克。 声明称，比克曾担任北加沙旅军事情报负责人，在该旅前任指挥官被打死后接任。",
