    "description": "新华社北京9月29日电（记者马晓冬）北京市第三中级人民法院9月29日依法公开宣判北京市重大项目建设指挥部办公室原保留正局级待遇干部刘辉受贿、挪用公款一案，对被告人刘辉以受贿罪判处有期徒刑十二年六个月，并处罚金人民币二百万元，以挪用公款罪判处有期徒刑六年，决定执行有期徒刑十五年，并处罚金人民币二百万元。对刘辉受贿犯罪所得及孳息依法予以追缴，上缴国库。",
