    "author": "吴雨,申铖",
    "description": "新华社北京9月29日电（记者申铖、吴雨）9月29日，财政部、中国人民银行、金融监管总局联合对外发布通知，明确自10月1日起，在全国范围内实施居民购房贷款贴息政策，政策实施期暂定1年。其间，符合条件的居民房贷可享受1个百分点的贴息支持。这是中央财政首次对商业性个人住房贷款进行贴息。 三部门印发的通知明确，对同时符合以下条件的居民家庭给予贴息支持：一是使用新发放的商业性个人住房贷款购买首套住房，不包括存量贷款置换。其中，“首套住房”的认定按…",
    "content": "新华社北京9月29日电（记者申铖、吴雨）9月29日，财政部、中国人民银行、金融监管总局联合对外发布通知，明确自10月1日起，在全国范围内实施居民购房贷款贴息政策，政策实施期暂定1年。其间，符合条件的居民房贷可享受1个百分点的贴息支持。这是中央财政首次对商业性个人住房贷款进行贴息。 三部门印发的通知明确，对同时符合以下条件的居民家庭给予贴息支持：一是使用新发放的商业性个人住房贷款购买首套住房，不包括存量贷款置换。其中，“首套住房”的认定按照现行政策执行，既包括新房也包括二手房。二是所购住房建筑面积不超过120平方米。…"
