    "content": "新华社北京9月29日电 美国国家航空航天局(NASA)28日宣布，将继续采用波音公司的“星际客机”执行不载人飞往国际空间站任务，但只有在该飞船“改进设计”后才会开展新的载人飞行任务。 就在今年2月，NASA发布调查报告认定，“星际客机”首次载人试飞任务出现的故障为严重程度等级最高的“A类”事故。此前美国“挑战者号”“哥伦比亚号”航天飞机事故均被认定为同类别事故。 2024年6月5日，美国波音公司“星际客机”飞船从佛罗里达州卡纳维拉尔角太空军基地发射升空。新华社发（美国国家航空航天局供图） NASA局长贾里德·艾萨克…"
