    "content": "最懂养生的一代人，最先对保健品冷静下来。 《2025年抖音银发市场线上消费与广告投放报告》出炉，占全体网民33.5%、高达3.76亿的50岁以上人群，在他们的购买榜单上，鲜花园艺以高达126.4的偏好指数强势领跑，酒类、生鲜和珠宝文玩紧随其后，被默认为“银发标配”的滋补保健类，连前四都没挤进去。 传统保健品巨头的财报也证明了这点，汤臣倍健两年营收累计减少30亿元。取而代之的是，精准营养成为了市场的香饽饽，2个月前小程序才刚上线的“营养日记”，以月费400元左右的精准方案，迅速打开局面，其中70%用户是中老年人。 一…"
