    "content": "中新网9月29日电 9月29日下午，国新办举行“开局起步‘十五五’”系列主题新闻发布会，介绍“十五五”时期推进科技强国建设有关情况。科技部副部长邱勇称诚实守信是中华民族的传统美德，严守科研诚信也是每一位科技工作者的基本操守。科技部会同有关部门，持续建立健全科研诚信相关制度机制，加强正面宣传教育和引导，坚持“零容忍”态度，严惩学术不端，持续营造风清气正的良好科研环境。"
