    "description": "“铁锂一哥”湖南裕能，刚刚度过“极度拉扯”的9月。一边是正经历业绩最好的年景，一边是资本端持续失温。公司的回应不是收缩而是借钱扩产：海内外产能建设同步提速，IPO、定增、H股接力融资....。但三重押注能否穿越行业扩产潮下 带来的2028年供给洪峰，尚待检验。这既是湖南裕能的“周期赌局”，也是锂电产业链的变革缩影。",
    "content": "“铁锂一哥”湖南裕能，刚刚度过“极度拉扯”的9月。一边是正经历业绩最好的年景，一边是资本端持续失温。公司的回应不是收缩而是借钱扩产：海内外产能建设同步提速，IPO、定增、H股接力融资....。但三重押注能否穿越行业扩产潮下 带来的2028年供给洪峰，尚待检验。这既是湖南裕能的“周期赌局”，也是锂电产业链的变革缩影。"
