    "content": "快科技9月29日消息，据Hardware Unboxed的实际测试， 《巫师3重制版》开启光线追踪后性能瓶颈严重，RTX 5090在1080p下平均仅62帧，而且这是在开启DLSS质量档的情况下。 更离谱的是，RTX 5080跑出了完全相同的62帧，RTX 5070 Ti也只差1帧，三张不同定位的显卡被锁在同一个水平线上，显然不是算力不够，而是游戏本身存在瓶颈。 RTX 5090在4K下开启DLSS性能档也只有59帧，和1080p的差距极小，测试使用的是锐龙7 9800X3D，CPU负载仅35%左右，没有核心跑满，…"
