    "content": "中新网9月29日电 9月29日下午，国新办举行“开局起步‘十五五’”系列主题新闻发布会，介绍“十五五”时期推进科技强国建设有关情况。科技部部长阴和俊指出，近年来，科技部与教育、人才等部门加强工作对接，强化规划衔接、政策协同、资源统筹、评价联动，合力推进教育科技人才一体发展。"
