    "content": "在2026抖音创作者大会上，记者见到了“00后”环球骑行创作者马壮（网名“湖远行”）。2018年，从事美发工作的他怀揣几千元积蓄，租下二手自行车从成都出发，开启骑行之路。至今，他的车轮已踏遍5个大洲、39个国家，行程累计11万公里。说起最初做互联网账号，他坦言：“因为穷，想吃互联网这碗饭”。 2026年9月，马壮在户外参加活动时与观众合影留念。新华社记者 黄智琪 摄 一路走来，马壮也曾陷入流量转瞬即逝的焦虑，为此，他日夜拼命创作。 如今，他放缓更新节奏，不再纠结短期得失。他的梦想是骑行全世界，坚持把骑行这件事一直做…"
